const scrollPositions = {};
const routeHistory = [];
const frameRoute = frame => typeof frame==='string'?frame:frame?.route;
const routeLabel = frame => ({browser:'Browser',library:'Bibliothek',inbox:'Feeds',search:'Suche',reader:'Reader Mode',discover:'Feed-Vorschau'}[frameRoute(frame)]||'vorherigen Ansicht');
function restoreFrame(frame){if(frame&&typeof frame==='object'){state.article=frame.article;state.hub=frame.hub;if(frame.route==='browser')state.browserArticle=frame.browserArticle;}navigate(frameRoute(frame)||'browser',true);if(frame&&typeof frame==='object')screen.scrollTop=frame.scroll;}
const state = {route:'browser',hub:'feeds',browserArticle:7,browserReturn:null,libraryOrigin:'Alle',filter:'Heute',libraryFilter:'Alle',article:1,query:'Kotlin',searchStatus:'Alle',searchFolder:'Alle',savedViews:[],rule:false,ruleTerm:'Gewinnspiel',ruleAction:'Ausblenden',ruleScope:'Alle Quellen',subscribed:false,imported:false,playing:false,queue:[2,4],notices:'Aus',interval:'Beim Öffnen',wifi:true,budget:'250 MB',discoveryPrivate:false,feedPreferences:{},noticeSources:'Regel: Kotlin',digestTime:'08:00',quietHours:true,dedup:true,subscriptionFolder:'Privat',subscriptionMode:'Reader-Volltext'};
const folders = () => ['Technik','Privat','Arbeit',...(state.newFolder?[state.newFolder]:[])];
const screen = document.querySelector('#screen');
const esc = text => String(text).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const action = (name,label,cls='btn',extra='') => `<button class="${cls}" data-action="${name}" ${extra}>${label}</button>`;
const header = (title,back=true) => `<div class="appbar">${back?action('back','‹','icon-btn','aria-label="Zurück"'):''}<h2>${title}</h2>${action('search','⌕','icon-btn tonal','aria-label="Artikel suchen"')}</div>`;
const row = (icon,title,sub,act) => `<button class="list-row" data-action="${act}"><span class="list-icon">${icon}</span><span class="grow"><strong>${title}</strong><small>${sub}</small></span><span class="chevron">›</span></button>`;
const panel = (title,text) => `<div class="panel"><h3>${title}</h3><p>${text}</p></div>`;
const field = (label,id,value,placeholder='') => `<label class="field" for="${id}">${label}</label><input type="text" id="${id}" value="${esc(value)}" placeholder="${placeholder}">`;
const select = (label,id,values,current) => `<label class="field" for="${id}">${label}</label><select id="${id}">${values.map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('')}</select>`;
const check = (label,id,checked,sub='') => `<label class="switch-row" for="${id}"><span>${label}<small>${sub}</small></span><input type="checkbox" id="${id}" ${checked?'checked':''}></label>`;

function bookmarkIcon(saved=false){
  const path=saved?'M17 3H7a2 2 0 0 0-2 2v16l7-3 7 3V5a2 2 0 0 0-2-2z':'M17 3H7a2 2 0 0 0-2 2v16l7-3 7 3V5a2 2 0 0 0-2-2zm0 15-5-2.18L7 18V5h10z';
  return `<svg class="bookmark-symbol" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path fill="currentColor" d="${path}"/></svg>`;
}
function queueIcon(queued=false){
  return `<svg class="queue-symbol" viewBox="0 0 28 24" aria-hidden="true" focusable="false"><path d="M3 6h9M3 12h7M3 18h9" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/><path d="M14 10h3l5-4v12l-5-4h-3z" fill="${queued?'currentColor':'none'}" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M25 9a5 5 0 0 1 0 6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>`;
}
function queueButton(a,menu=false){
  const queued=state.queue.includes(a.id);
  const label=(queued?'Aus Vorleseliste entfernen: ':'Zur Vorleseliste hinzufügen: ')+a.title;
  const content=menu?`<span class="list-icon">${queueIcon(queued)}</span><span class="grow"><strong>Vorleseliste</strong><small class="queue-description">${queued?'Hinzugefügt · antippen zum Entfernen':'Zum späteren Anhören hinzufügen'}</small></span>`:queueIcon(queued);
  return action('queue-toggle',content,menu?'list-row queue-menu':'queue-toggle',`data-id="${a.id}" aria-label="${esc(label)}" title="${esc(label)}" aria-pressed="${queued}"`);
}
function syncQueueButtons(){
  document.querySelectorAll('[data-action="queue-toggle"]').forEach(button=>{
    const a=articles.find(article=>article.id===Number(button.dataset.id));
    const queued=state.queue.includes(a.id);
    const label=(queued?'Aus Vorleseliste entfernen: ':'Zur Vorleseliste hinzufügen: ')+a.title;
    button.setAttribute('aria-pressed',String(queued));
    button.setAttribute('aria-label',label);
    button.title=label;
    button.querySelector('.queue-symbol').outerHTML=queueIcon(queued);
    const description=button.querySelector('.queue-description');
    if(description)description.textContent=queued?'Hinzugefügt · antippen zum Entfernen':'Zum späteren Anhören hinzufügen';
  });
}

function articleCard(a) {
  return `<article class="article-card ${a.read?'read':''}"><button class="article-main" data-action="article" data-id="${a.id}"><span class="source"><span class="source-icon">${a.icon}</span>${a.source}<span>· ${a.time}</span></span><h3>${a.title}</h3><p>${a.description}</p></button><div class="article-meta"><span>${a.minutes} Min.</span>${a.offline?'<span class="tag green">✓ Offline</span>':''}${state.route==='library'?'<span class="tag">'+(a.origin==='web'?'Webseite':'Feed')+'</span>':''}${a.updated?'<button class="tag pink" data-action="changes">Aktualisiert</button>':''}<span class="spacer"></span>${queueButton(a)}<button class="save-btn" data-action="save" data-id="${a.id}" aria-label="${a.saved?'Merker entfernen':'Für später merken'}" aria-pressed="${a.saved}">${bookmarkIcon(a.saved)}</button></div>${a.duplicates?action('duplicates','↳ Auch in 2 weiteren Quellen','duplicate'):''}</article>`;
}
function inbox() {
  const list=feedArticles().filter(a=>state.filter==='Ungelesen'?!a.read:state.filter==='Gemerkt'?a.saved:state.filter==='Heute'?a.time!=='gestern':true);
  const counts={'Heute':feedArticles().filter(a=>a.time!=='gestern').length,'Ungelesen':feedArticles().filter(a=>!a.read).length,'Gemerkt':feedArticles().filter(a=>a.saved).length,'Alle':feedArticles().length};
  return `${header('Feeds') }<div class="hero"><span class="overline">DONNERSTAG, 22. OKTOBER</span><h3>Ein bisschen<br>mehr Durchblick.</h3><p>${counts.Ungelesen} ungelesene Beiträge aus deinen Quellen.</p><span class="hero-art" aria-hidden="true">✳</span></div><div class="chips">${Object.keys(counts).map(f=>action('filter',`${f} <span class="count">${counts[f]}</span>`,`chip ${state.filter===f?'selected':''}`,`data-value="${f}" aria-pressed="${state.filter===f}"`)).join('')}</div><div class="section-heading"><h3>${state.filter} · ${list.length}</h3>${action('mark-all','Alle als gelesen','text-btn')}</div>${list.length?list.map(articleCard).join(''):empty('Alles gelesen.','Deine nächste Pause gehört dir. Neue Beiträge erscheinen hier.')}<div class="section-heading">${action('refresh','↻ Aktualisieren','text-btn')}${action('catalog','+ Quelle entdecken','text-btn')}</div>`;
}
function empty(title,text){return `<div class="empty"><div class="empty-icon">✳</div><h3>${title}</h3><p>${text}</p></div>`;}
function discover(){return `${header('Feed entdeckt',true)}<div class="hero"><span class="overline">AUF DIESER WEBSITE</span><h3>Field Notes</h3><p>Gedanken zu einem selbstbestimmten Internet.</p><span class="hero-art" aria-hidden="true">◎</span></div><div class="source">fieldnotes.example/feed.xml · RSS</div><div class="section-heading"><h3>Vorschau · neueste Beiträge</h3></div>${state.discoveryPrivate?panel('Das offene Web braucht keine endlose Timeline','Beispielvorschau · keine Speicherung im privaten Tab.'):articleCard({...articles[1],source:'Field Notes'})}${select('Ordner','discover-folder',folders(),state.subscriptionFolder)}${select('Artikel öffnen als','discover-mode',['Reader-Volltext','Feed-Inhalt','Originalseite'],state.subscriptionMode)}<div class="button-row">${action('subscribe',state.subscribed?'✓ Abonniert':'Quelle abonnieren','btn wide',state.subscribed?'disabled':'')}</div>${action('manual','Feed-Adresse eingeben','text-btn wide')}${action('private-preview',state.discoveryPrivate?'Normalen Tab zeigen':'Privaten Tab zeigen','text-btn wide')}${state.discoveryPrivate?panel('Privater Tab','Vorschau möglich. Abonnements und Lesestände werden hier nicht gespeichert.'):''}`;}
function sources(){return `${header('Quellen') }<p class="hint">Profil Privat · ${4+(state.subscribed?1:0)+(state.imported?2:0)+catalogPrototype.subscriptionCount()} Quellen</p>${action('catalog','+ Quellen hinzufügen','btn wide')}${action('catalog-manual','Feed-Adresse eingeben','text-btn wide')}<div class="section-heading"><h3>Ordner</h3>${action('new-folder','+ Neu','text-btn')}</div>${row('⌘','Technik','Android Journal · Kotlin Notes','folder-tech')}${row('◎','Privat','Open Web · Slow Sunday','folder-private')}${state.newFolder?row('▤',esc(state.newFolder),'Eigener Ordner','empty-folder'):''}<div class="section-heading"><h3>Alle Quellen</h3></div>${feedArticles().map(a=>row(a.icon,a.source,a.id===3?'Aktualisierung fehlgeschlagen':'Zuletzt aktualisiert: 09:38',`feed-${a.id}`)).join('')}${state.subscribed?row('◎','Field Notes','Ordner '+esc(state.subscriptionFolder),'subscribed-feed'):''}${catalogPrototype.subscriptionRows()}${state.imported?row('D','Design Notes','Importiert · Design','imported-feed')+row('L','Local Journal','Importiert · Privat','imported-feed'):''}`;}
function library(){
  const list=libraryArticles().sort((a,b)=>Number(!!b.legacy)-Number(!!a.legacy)).filter(a=>(state.libraryFilter==='Alle'||state.libraryFilter==='Offline'&&a.offline||state.libraryFilter==='Ungelesen'&&!a.read||state.libraryFilter==='Gemerkt'&&a.saved)&&(state.libraryOrigin==='Alle'||(a.origin==='web'?'Webseiten':'Feeds')===state.libraryOrigin));
  return `${header('Bibliothek')}<div class="library-summary"><span class="library-symbol">▥</span><div><b>Alles, was du behalten möchtest.</b><small>Webseiten und Feeds · ${libraryArticles().length} Artikel</small></div></div><div class="origin-tabs" role="tablist" aria-label="Artikelherkunft">${['Alle','Webseiten','Feeds'].map(v=>action('library-origin',v,`origin-tab ${state.libraryOrigin===v?'selected':''}`,`data-value="${v}" role="tab" aria-selected="${state.libraryOrigin===v}"`)).join('')}</div><div class="chips">${['Alle','Offline','Ungelesen','Gemerkt'].map(v=>action('library-filter',v,`chip ${state.libraryFilter===v?'selected':''}`,`data-value="${v}" aria-pressed="${state.libraryFilter===v}"`)).join('')}</div><div class="section-heading"><h3>${list.length} Artikel</h3>${action('offline','Downloads verwalten','text-btn')}</div>${list.map(articleCard).join('')||empty('Hier ist noch Platz.','Artikel im Reader offline speichern oder in Feeds merken.')}<div class="button-row">${action('audio',queueIcon()+'Vorleseliste','btn secondary wide queue-link')}</div><p class="hint">Die Beispiele von Web Almanach und Papier & Pixel stehen für deine bisherigen Reader-Speicherungen.</p>`;
}
function offline(){return `${header('Für unterwegs',true)}<div class="panel"><span class="overline">OFFLINE AUF DIESEM GERÄT</span><h3>${articles.filter(a=>a.offline).length} Artikel verfügbar</h3><p>Demo-Speicheranzeige · 36 MB von ${state.budget}</p><div class="meter"><span></span></div></div>${check('Nur über WLAN laden','wifi',state.wifi)}${select('Speicherbudget · Vorschlag','budget',['100 MB','250 MB','500 MB'],state.budget)}<div class="section-heading"><h3>Leseliste</h3></div>${libraryArticles().map(a=>`<label class="check-row"><input type="checkbox" name="download" value="${a.id}" ${!a.offline?'checked':''}><span>${a.title}<small>${a.offline?'✓ Bereits offline':'Noch nicht geladen'}</small></span></label>`).join('')}<div class="button-row">${action('download','Auswahl laden','btn wide')}${action('remove-downloads','Offline-Dateien entfernen','btn outline wide')}</div>${action('download-error','Fehlerzustand ansehen','text-btn wide')}<p class="hint">Gemerkte Artikel bleiben beim automatischen Aufräumen erhalten. Downloads entfernen löscht keine Abos oder Merker.</p>`;}
function rules(){return `${header('Filter & Regeln',true)}<p class="hint">Weniger Rauschen. Mehr von dem, was zählt.</p>${state.rule?panel('Aktive Regel',`${esc(state.ruleScope)} · Titel enthält „${esc(state.ruleTerm)}“ → ${esc(state.ruleAction)}`):panel('Deine erste Regel','Vorschau prüfen. Erst danach aktivieren.')}<form id="rule-form">${select('Anwenden auf','rule-scope',['Alle Quellen','Technik','Privat'],state.ruleScope)}${field('Titel enthält','rule-term',state.ruleTerm)}${select('Dann','rule-action',['Ausblenden','Für später merken','Benachrichtigung vormerken'],state.ruleAction)}<div class="button-row">${action('rule-preview','Treffer prüfen','btn secondary')}${action('rule-save',state.rule?'Regel aktualisieren':'Regel aktivieren','btn')}</div></form>${state.rule?action('rule-delete','Regel entfernen','text-btn wide'):''}${action('hidden-items','Ausgeblendete Beiträge ansehen','text-btn wide')}<div class="section-heading"><h3>Suche als Ansicht</h3></div>${row('⌕','Kotlin entdecken','Begriff + Ordner + Gelesen-Status','search')}${state.savedViews.map((v,i)=>row('⌕',esc(v.name),`${esc(v.query)} · ${esc(v.status)}`,`view-${i}`)).join('')}${check('Gleiche Artikel-URLs zusammenführen','dedup',state.dedup,'Ähnliche Titel nur als Quellengruppe anzeigen.')}`;}
function search(){return `${header('Artikel suchen',true)}<div class="search-bar"><svg aria-hidden="true" viewBox="0 0 24 24"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/></svg><input id="search-query" type="search" value="${esc(state.query)}" aria-label="Artikel suchen" placeholder="Titel oder Text durchsuchen"><button data-action="clear-search" aria-label="Suche löschen" ${state.query?'':'hidden'}>×</button></div>${select('Ordner','search-folder',['Alle','Technik','Privat'],state.searchFolder)}${select('Lesestatus','search-status',['Alle','Ungelesen','Gelesen'],state.searchStatus)}<div class="button-row">${action('run-search','Suchen','btn')}${action('save-view','Ansicht speichern','btn secondary')}</div><div id="search-results">${searchResults()}</div>`;}
function searchResults(){const query=state.query.toLocaleLowerCase('de');const result=articles.filter(a=>(a.title+' '+a.description).toLocaleLowerCase('de').includes(query)&&(state.searchFolder==='Alle'||a.topic===state.searchFolder)&&(state.searchStatus==='Alle'||a.read===(state.searchStatus==='Gelesen')));return `<div class="section-heading"><h3>${result.length} Treffer</h3></div>${result.length?result.map(articleCard).join(''):empty('Keine Treffer','Versuche einen anderen Begriff oder lockere deine Filter.')}`;}
function audio(){const queue=state.queue.map(id=>articles.find(a=>a.id===id));return `${header('Vorleseliste',true)}<div class="player-art" aria-hidden="true">≋</div><span class="overline">${state.playing?'WIEDERGABE SIMULIERT':'BEREIT ZUM ZUHÖREN'}</span><h3>${queue[0]?.title||'Deine Liste ist leer'}</h3><div class="meter"><span style="width:${state.playing?'25':'0'}%"></span></div><div class="timeline"><span>${state.playing?'1:30':'0:00'}</span><span>${queue[0]?.minutes||0}:00</span></div><div class="player-controls">${action('speed','1×','text-btn')}${action('play',state.playing?'Ⅱ':'▷','play',`aria-label="${state.playing?'Pausieren':'Vorlesen starten'}"`)}${action('next-audio','▷|','icon-btn','aria-label="Nächster Beitrag"')}</div><div class="section-heading"><h3>Warteschlange · ${queue.length}</h3>${action('queue-library','Leseliste übernehmen','text-btn')}</div>${queue.map((a,i)=>`<div class="list-row"><span class="number">${i+1}</span><span class="grow"><strong>${a.title}</strong><small>${a.minutes} Min. · ${a.source}</small></span>${i?action('queue-up','↑','icon-btn',`data-id="${a.id}" aria-label="Nach oben verschieben"`):''}${action('queue-remove','×','icon-btn',`data-id="${a.id}" aria-label="Aus Warteschlange entfernen"`)}</div>`).join('')}<p class="hint">Demo ohne Audio. Geplant: Android-Vorlesen in der geöffneten Sitzung. Hintergrundwiedergabe als eigener Ausbau.</p>${action('voice-error','Fehlende Stimme ansehen','text-btn wide')}`;}
function settings(){return `${header('Einstellungen',true)}<span class="overline">HINWEISE</span>${select('Benachrichtigungen','notice-mode',['Aus','Nur ausgewählte Treffer','Tägliche Zusammenfassung'],state.notices)}${select('Quellen / Regeln','notice-sources',['Gemerkte Quellen','Regel: Kotlin','Alle Quellen'],state.noticeSources)}${select('Zielzeit der Zusammenfassung','digest-time',['08:00','18:00','20:00'],state.digestTime)}${check('Ruhezeit 22:00–08:00','quiet-hours',state.quietHours)}${action('notice-preview','Vorschau ansehen','text-btn wide')}${action('permission-error','Berechtigung fehlt · Zustand','text-btn wide')}<div class="section-heading"><h3>Aktualisierung</h3></div>${select('Feeds abrufen','refresh-mode',['Beim Öffnen','Etwa stündlich','Etwa alle 6 Stunden'],state.interval)}<p class="hint">Hintergrundabrufe und Zusammenfassungen können sich durch das Betriebssystem verzögern.</p><div class="section-heading"><h3>Profil & Datenschutz</h3></div>${panel('Profil Privat','Vorschlag: Abos, Regeln und Lesestände gehören zu diesem normalen Profil. „Privat“ ist hier der Profilname, nicht der private Browsermodus.')}<p class="hint">Private Tabs speichern keine Feed-Daten. Gesperrte Profile zeigen keine Artikelvorschau in Hinweisen.</p>${action('settings-save','Einstellungen übernehmen','btn wide')}`;}
function importPage(){return `${header('Import & Export',true)}<div class="hero"><span class="overline">DEINE QUELLEN ZIEHEN MIT</span><h3>Schon eine<br>Sammlung?</h3><p>Abos und Ordner mit einer OPML-Datei übernehmen.</p></div>${action('import-preview','Beispiel-OPML prüfen','btn wide')}<p class="hint">Dieser Entwurf verwendet eine Beispieldatei. Es wird keine Datei von deinem Gerät gelesen.</p><div class="section-heading"><h3>Vorschau · meine-feeds.opml</h3></div><div class="list-row"><span class="list-icon">+</span><span class="grow"><strong>2 neue Quellen</strong><small>Design Notes · Local Journal</small></span></div><div class="list-row"><span class="list-icon">✓</span><span class="grow"><strong>1 bereits vorhanden</strong><small>Open Web · wird übersprungen</small></span></div><div class="list-row"><span class="list-icon">!</span><span class="grow"><strong>1 ungültige Adresse</strong><small>HTTP(S)-Adresse fehlt · wird nicht importiert</small></span></div>${check('Ordnerstruktur übernehmen','import-folders',true)}<div class="button-row">${action('import-confirm',state.imported?'✓ Importiert':'2 Quellen importieren','btn wide',state.imported?'disabled':'')}${action('export','OPML-Export ansehen','btn outline wide')}</div><p class="hint">Export enthält Abos und Ordner. Keine Artikel, Lesestände oder Zugangsdaten.</p>`;}
function reader(){const a=articles.find(a=>a.id===state.article);return `<article class="reader-article"><h2>${a.title}</h2><div class="byline">Redaktion · 22. Oktober · ${a.minutes} Min. Lesezeit</div><p>Es gibt diesen kleinen Moment am Morgen: Die Welt ist schon laut, aber der Tag gehört noch dir.</p><p>Ein guter Reader macht daraus keine Aufgabe. Er sammelt die Stimmen, die du selbst gewählt hast. Und lässt dich entscheiden, wann du ihnen zuhörst.</p><p>Manche Geschichten liest du sofort. Andere hebst du auf. Nicht alles muss heute fertig werden, und nicht jede neue Meldung verdient eine Unterbrechung.</p><p>So wird aus einer Liste von Links wieder ein Ort zum Lesen. Übersichtlich, persönlich und so ruhig, wie du es gerade brauchst.</p><p class="byline">Beispielartikel für diesen Entwurf.</p></article><div class="reader-pill"><span>${articleDomain(a)} / journal</span>${queueButton(a)}${action('reader-menu','⋯','icon-btn','aria-label="Reader-Aktionen öffnen"')}</div>`;}
function changes(){return `${header('Artikel aktualisiert',true)}<span class="tag pink">Heute · 09:30</span><h3>Ein kleines Update. Ein spürbar besserer Alltag.</h3><p class="hint">Vergleich mit deiner zuletzt gespeicherten Fassung.</p><div class="version"><span class="overline">VORHER · 08:15</span><p>Das Update erscheint <del>am Freitag für alle Geräte</del>.</p></div><div class="version"><span class="overline">AKTUELL · 09:30</span><p>Das Update erscheint <ins>ab Montag schrittweise für unterstützte Geräte</ins>.</p></div>${action('article','Aktuelle Fassung lesen','btn wide','data-id="1"')}<div class="callout">Ohne lokal gespeicherte Vorversion gibt es nur einen Aktualisierungshinweis. Kein erfundener Vergleich.</div>`;}
function tools(){return `${header('Werkzeuge')}${row('≡','Filter & Regeln',state.rule?'1 Regel aktiv':'Weniger Rauschen, passende Inhalte','rules')}${row('⌕','Gespeicherte Suchen',`${state.savedViews.length} eigene Ansichten`,'search')}${row('↓','Offline-Verwaltung','Downloads und Speicherbudget','offline')}${row('⇄','Import & Export','Feed-Sammlung mitnehmen','import')}${row('◉','Hinweise & Einstellungen','Aktualisierung und Datenschutz','settings')}${row('✳','Späterer Ausbau','Newsletter, Podcasts und Sync','roadmap')}<div class="section-heading"><h3>Weitere Demo-Zustände</h3></div><div class="chips">${action('empty-demo','Leere Inbox','chip')}${action('network-error','Ladefehler','chip')}${action('private-demo','Privatmodus','chip')}</div>`;}
function roadmap(){return `${header('Der ganze Entwurf',true)}${[['01','Basis','Feed-Erkennung, Vorschau, Abos, smarte Inbox, Gelesen-Status, Ordner, OPML und profilbezogene Speicherung.'],['02','Lesekomfort','Ansicht pro Quelle, Reader-Volltext, Leseliste, Tags, Offline-Pakete, Speicherbudget und Android-Vorleseliste.'],['03','Fokus','Regeln, gespeicherte Suchen, Dublettengruppen, gezielte Hinweise, täglicher Digest und Artikelvergleich.'],['04','Verbindungen','Newsletter-Empfang, Podcasts sowie Sync von Abos, Merkern und Leseständen. Eigene Infrastruktur- und Plattformplanung.']].map(([n,title,text])=>`<div class="roadmap-step"><span class="overline">AUSBAUSTUFE ${n}</span><h3>${title}</h3><p>${text}</p></div>`).join('')}<div class="callout">Vorschläge zur Abstimmung: profilgebundene Abos, 250 MB Offline-Budget, kein automatischer Download über Mobilfunk, Hinweise standardmäßig aus.</div>${action('future-details','Erweiterungen ansehen','btn secondary wide')}`;}
function browser(){
  const a=articles.find(a=>a.id===state.browserArticle);
  return `<div class="website"><div class="site-mast"><span>${a.source}</span><span aria-hidden="true">☰</span></div><div class="site-kicker">JOURNAL / GEDANKEN ZUM WEB</div><h2>${a.title}</h2><p class="site-intro">Für die Dinge, die bleiben sollen. Und die Freiheit, später weiterzulesen.</p><div class="site-art" aria-hidden="true"><div class="paper paper-back"></div><div class="paper paper-front"><span>Ein guter<br>Gedanke.</span><i></i><i></i><i></i></div><span class="art-star">✳</span></div><div class="site-byline">REDAKTION · ${a.minutes} MIN. LESEZEIT</div><p>Manchmal finden wir einen Text genau im falschen Moment. Zwischen zwei Terminen, unterwegs, kurz bevor der Zug im Tunnel verschwindet.</p><p>Die Lösung muss nicht noch ein offener Tab sein. Ein guter Artikel darf seinen eigenen Platz bekommen – und dort warten, bis wieder Zeit ist.</p><h3>Wiederfinden statt offen lassen.</h3><p>Speichere ihn für später. Lies ihn ohne Ablenkung. Oder folge dieser Quelle, wenn du ihre nächsten Gedanken nicht verpassen möchtest.</p><div class="site-foot">Beispielwebsite · keine externe Verbindung</div></div><div class="browser-chrome"><button class="tab-count" data-action="browser-tabs" aria-label="Tabübersicht">3</button><button class="browser-address" data-action="address-edit" title="Lange drücken: Reader Mode">${articleDomain(a)}</button>${action('new-tab','+','icon-btn','aria-label="Neuer Tab"')}${action('browser-menu','⋮','icon-btn','aria-label="Browser-Menü öffnen"')}</div>${state.browserReturn?`<button class="return-reading" data-action="return-reading">‹ Zurück zu ${routeLabel(state.browserReturn)}</button>`:''}`;
}
function openHub(route){
  state.hub=route==='library'?'library':'feeds';
  state.browserReturn=null;
  routeHistory.length=0;
  routeHistory.push('browser');
  navigate(route,true);
}
function goBack(){
  if(document.querySelector('#sheet').open){closeSheet();return;}
  if(state.route==='browser'&&state.browserReturn){const target=state.browserReturn;state.browserReturn=null;restoreFrame(target);return;}
  restoreFrame(routeHistory.pop()||'browser');
}
function browserMenu(){
  const a=articles.find(a=>a.id===state.browserArticle);
  const unread=feedArticles().filter(article=>!article.read).length;
  const feedEntry=`<button class="list-row feed-menu-row" data-action="open-feeds"><span class="list-icon">◉</span><span class="grow"><strong>Feeds</strong><small>Beiträge deiner Quellen</small></span>${unread?`<span class="feed-count" aria-label="${unread} ungelesene Beiträge"><b>${unread}</b> ungelesen</span>`:''}<span class="chevron">›</span></button>`;
  sheet('',`<div class="menu-address"><span>◉</span><b>${articleDomain(a)}</b></div><div class="menu-shortcuts">${[['↓','Downloads','existing-feature'],['▤','Reader Mode','browser-reader'],['☆','Favoriten','existing-feature'],['◷','Verlauf','existing-feature'],['⚙','Einstellungen','existing-feature']].map(([icon,label,act])=>`<button data-action="${act}" data-label="${label}"><span>${icon}</span>${label}</button>`).join('')}</div><div class="menu-scroll"><div class="section-heading"><h3>Auf dieser Seite</h3></div>${row('⌕','Auf Seite suchen','Bestehende Browser-Aktion','existing-feature')}${row('↗','Seite teilen','Bestehende Browser-Aktion','existing-feature')}${state.browserArticle===7?row('◉','Feed entdeckt · Field Notes',state.subscribed?'Bereits abonniert':'Vorschau ansehen und abonnieren','browser-discover'):''}<section class="menu-secondary" aria-label="Lesen und sammeln"><div class="section-heading"><h3>Lesen & sammeln</h3></div>${feedEntry}${row('▥','Bibliothek',`${libraryArticles().length} gespeicherte Artikel · Webseiten und Feeds`,'open-library')}</section><details class="menu-workflows"><summary>Eigene Abläufe<span aria-hidden="true">⌄</span></summary><p>Hier erscheinen deine konfigurierten Abläufe. Im Entwurf sind keine Beispielabläufe hinterlegt.</p></details></div><div class="menu-footer">${[['‹','Zurück'],['›','Vorwärts'],['↻','Neu laden'],['☆','Favorit'],['♧','Anheften']].map(([icon,label])=>action(label==='Zurück'?'menu-dismiss':'existing-feature',icon,'icon-btn',`aria-label="${label}" data-label="${label}"`)).join('')}</div>`);
  document.querySelector('#sheet').classList.add('browser-menu-sheet');
  document.querySelector('.phone').classList.add('menu-open');
}
const renderers={catalog:()=>catalogPrototype.render(),browser,inbox,discover,sources,library,rules,audio,settings,import:importPage,roadmap,reader,offline,search,changes,tools};
function render(){
  document.querySelector('.phone').classList.toggle('reader-mode',state.route==='reader');
  document.querySelector('.phone').classList.toggle('browser-mode',state.route==='browser');
  document.querySelector('#bottom-nav').hidden=state.route==='browser'||state.route==='reader'||state.hub==='library';
  document.querySelector('#system-back').hidden=state.route==='browser'&&!state.browserReturn;
  document.querySelector('#location-trail').textContent=state.route==='browser'?'Browser · '+articleDomain(articles.find(a=>a.id===state.browserArticle)):state.route==='reader'?'Reader Mode · zurück zu '+(frameRoute(routeHistory.at(-1))==='library'?'Bibliothek':frameRoute(routeHistory.at(-1))==='browser'?'Browser':'Feeds'):state.route==='library'?'Bibliothek · Webseiten & Feeds':'Candy Feeds · '+(routes.find(r=>r[0]===state.route)?.[1]||'Detailansicht');
  screen.innerHTML=renderers[state.route]();
  catalogPrototype.afterRender();
  if(state.route==='reader')state.renderedArticle=state.article;
  document.querySelector('#scenarios').innerHTML=routes.map(([r,title],i)=>`<button class="scenario ${r===state.route?'active':''}" data-route="${r}" ${r===state.route?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${title}</span></button>`).join('');
  const active=['catalog','discover','sources','import'].includes(state.route)?'sources':['library','reader','offline','audio'].includes(state.route)?'library':state.route==='inbox'?'inbox':'tools';
  document.querySelector('#bottom-nav').innerHTML=[['inbox','▤','Inbox'],['library','▥','Bibliothek'],['sources','◉','Quellen'],['tools','☷','Werkzeuge']].map(([r,icon,label])=>`<button data-route="${r}" class="${active===r?'active':''}" ${active===r?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${label}</button>`).join('');
  const [title,description,phase,rows]=notes[state.route];
  document.querySelector('#notes-content').innerHTML=`<h2>${title}</h2><p>${description}</p><span class="phase">${phase}</span><div style="margin-top:24px">${rows.map(([h,p])=>`<div class="note-row"><b>${h}</b><p>${p}</p></div>`).join('')}</div>`;
}
function navigate(route,back=false){scrollPositions[state.route]=screen.scrollTop;if(!back&&route!==state.route)routeHistory.push({route:state.route,article:state.renderedArticle||state.article,hub:state.hub,scroll:screen.scrollTop,browserArticle:state.browserArticle});state.route=renderers[route]?route:'inbox';state.playing=false;document.querySelector('#toast').hidden=true;closeSheet();render();screen.scrollTop=scrollPositions[state.route]||0;history.replaceState(null,'','#'+state.route);}
let toastTimer;
let undoAction;
function toast(message,undo,openQueue=false){const el=document.querySelector('#toast');clearTimeout(toastTimer);undoAction=undo;el.innerHTML=esc(message)+(undo?'<button data-action="undo">Rückgängig</button>':'')+(openQueue?'<button data-action="audio">Liste öffnen</button>':'');el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,undo?10000:4200);}
function positionSheet(){const rect=document.querySelector('.phone').getBoundingClientRect();const modal=document.querySelector('#sheet');Object.assign(modal.style,{position:'fixed',left:(rect.left+7)+'px',top:'auto',right:'auto',bottom:(innerHeight-rect.bottom+7)+'px',width:(rect.width-14)+'px',maxHeight:(rect.height-50)+'px'});}
function closeSheet(){catalogPrototype.cancelPreview();document.querySelector('#sheet').close();document.querySelector('#sheet').classList.remove('browser-menu-sheet','catalog-sheet');document.querySelector('.phone').classList.remove('menu-open');}
function sheet(title,body){catalogPrototype.cancelPreview();document.querySelector('#sheet').classList.remove('browser-menu-sheet','catalog-sheet');document.querySelector('.phone').classList.remove('menu-open');document.querySelector('#sheet-content').innerHTML=`<h2>${title}</h2>${body}`;positionSheet();document.querySelector('#sheet').showModal();}
window.addEventListener('resize',positionSheet);
window.addEventListener('scroll',()=>{if(document.querySelector('#sheet').open)positionSheet();});
function value(id){return document.getElementById(id)?.value;}
function captureRule(){state.ruleTerm=value('rule-term').trim();state.ruleScope=value('rule-scope');state.ruleAction=value('rule-action');}
function ruleMatches(){return feedArticles().filter(a=>a.title.toLowerCase().includes(state.ruleTerm.toLowerCase())&&(state.ruleScope==='Alle Quellen'||a.topic===state.ruleScope));}
document.addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button)return;
  if(button.dataset.route){const target=button.dataset.route;if(button.closest('#scenarios')){state.hub=target==='library'?'library':'feeds';routeHistory.length=0;routeHistory.push('browser');}else if(button.closest('#bottom-nav')){routeHistory.length=0;routeHistory.push('browser');}navigate(target,true);return;}
  const act=button.dataset.action;const id=Number(button.dataset.id);const a=articles.find(a=>a.id===(id||state.article));
  if(renderers[act]){navigate(act);return;}
  switch(act){
    case 'back':goBack();break;
    case 'browser-menu':browserMenu();break;
    case 'menu-dismiss':closeSheet();break;
    case 'open-feeds':state.filter='Ungelesen';openHub('inbox');break;
    case 'open-library':openHub('library');break;
    case 'browser-reader':state.hub='library';state.article=state.browserArticle;articles.find(a=>a.id===state.article).read=true;navigate('reader');break;
    case 'browser-discover':state.hub='feeds';navigate('discover');break;
    case 'return-reading':{const target=state.browserReturn||'library';state.browserReturn=null;restoreFrame(target);break;}
    case 'browser-tabs':sheet('Deine Tabs',row('F','Field Notes','Aktuell geöffnet','tab-current')+row('W','Web Almanach','Beispieltab','tab-web')+row('P','Papier & Pixel','Beispieltab','tab-paper'));break;
    case 'tab-current':case 'tab-web':case 'tab-paper':state.browserArticle=act==='tab-current'?7:act==='tab-web'?5:6;state.browserReturn=null;navigate('browser',true);break;
    case 'new-tab':sheet('Neuer Tab','<p>Der reguläre Candy-Tab bleibt unabhängig von Feeds und Bibliothek. Für diesen Entwurf kannst du eine Beispielseite öffnen.</p>'+action('tab-current','Field Notes öffnen','btn wide'));break;
    case 'address-edit':sheet('Adresse & Reader',field('Aktuelle Adresse','browser-url','https://'+articleDomain(articles.find(a=>a.id===state.browserArticle)))+'<p>Wie in Candy: langes Drücken auf die Adressleiste öffnet standardmäßig Reader Mode.</p>'+action('browser-reader','Im Reader Mode lesen','btn wide'));break;
    case 'existing-feature':sheet(button.dataset.label||button.innerText,'<p>Bestehende Browser-Funktion, hier zur Orientierung gezeigt. Die Demo konzentriert sich auf Feeds, Bibliothek und Reader Mode.</p>');break;
    case 'library-origin':state.libraryOrigin=button.dataset.value;render();break;
    case 'filter':state.filter=button.dataset.value;render();break;
    case 'library-filter':state.libraryFilter=button.dataset.value;render();break;
    case 'article':state.article=id||1;articles.find(a=>a.id===state.article).read=true;navigate('reader');break;
    case 'save':a.saved=!a.saved;render();toast(a.saved?'Für später gemerkt.':a.offline||a.inLibrary?'Merker entfernt. Artikel bleibt in Bibliothek.':'Merker entfernt.');break;
    case 'queue-toggle':{
      const queued=state.queue.includes(a.id);
      if(queued){if(state.queue[0]===a.id)state.playing=false;state.queue=state.queue.filter(id=>id!==a.id);}
      else state.queue.push(a.id);
      syncQueueButtons();
      if(button.closest('#sheet'))closeSheet();
      toast(queued?'Aus Vorleseliste entfernt.':'Zur Vorleseliste hinzugefügt.',undefined,true);
      break;
    }
    case 'mark-all':{const old=feedArticles().map(a=>a.read);feedArticles().forEach(a=>a.read=true);render();toast('Alle Beiträge als gelesen markiert.',()=>{feedArticles().forEach((a,i)=>a.read=old[i]);render();});break;}
    case 'undo':undoAction?.();document.querySelector('#toast').hidden=true;break;
    case 'refresh':toast('Demo aktualisiert. Keine neuen Beiträge.');break;
    case 'duplicates':sheet('Eine Geschichte, drei Quellen',row('◎','Open Web','Originalartikel · 6 Min.','article-2')+row('D','Daily Web','Andere Perspektive · 4 Min.','related-source')+row('L','Local Journal','Einordnung · 5 Min.','related-source')+'<p>Ähnliche Titel werden gruppiert. Du entscheidest, welche Quelle du liest.</p>');break;
    case 'article-2':state.article=2;navigate('reader');break;
    case 'related-source':sheet('Weitere Quelle','<p>In der App öffnet sich hier die gewählte Quelle. Im Entwurf sind diese Artikel nicht hinterlegt.</p>');break;
    case 'subscribe':if(state.discoveryPrivate){sheet('Privater Tab','<p>Hier werden keine Abos gespeichert. Öffne die Website in einem normalen Profil, um ihr dauerhaft zu folgen.</p>');}else{state.subscribed=true;state.subscriptionFolder=value('discover-folder');state.subscriptionMode=value('discover-mode');render();toast('Quelle abonniert · '+state.subscriptionFolder);}break;
    case 'private-preview':state.discoveryPrivate=!state.discoveryPrivate;render();break;
    case 'manual':sheet('Feed-Adresse eingeben',field('HTTP(S)-Adresse','manual-url','','https://…')+action('manual-check','Adresse prüfen','btn wide'));break;
    case 'manual-check':try{const url=new URL(value('manual-url'));if(!['http:','https:'].includes(url.protocol))throw Error();sheet('Adresse gültig','<p>Der Entwurf prüft das Format, ruft aber keinen Feed ab.</p>'+action('discover','Beispielvorschau öffnen','btn wide'));}catch{sheet('Adresse prüfen','<p>Bitte eine vollständige HTTP(S)-Adresse eingeben.</p>'+action('manual','Erneut eingeben','btn wide'));}break;
    case 'new-folder':sheet('Ordner erstellen',field('Name','folder-name','')+action('folder-create','Erstellen','btn wide'));break;
    case 'folder-create':if(!value('folder-name').trim())return;state.newFolder=value('folder-name').trim();document.querySelector('#sheet').close();render();break;
    case 'folder-tech':case 'folder-private':state.searchFolder=act==='folder-tech'?'Technik':'Privat';state.query='';navigate('search');break;
    case 'empty-folder':sheet('Noch keine Quellen','<p>Beim Abonnieren kannst du eine Quelle diesem Ordner zuordnen.</p>'+action('discover','Quelle hinzufügen','btn wide'));break;
    case 'feed-save':state.feedPreferences[state.editFeed]={mode:value('feed-mode'),folder:value('feed-folder'),notice:document.querySelector('#feed-notice').checked};document.querySelector('#sheet').close();toast('Quelleneinstellung im Entwurf übernommen.');break;
    case 'download':{const chosen=[...document.querySelectorAll('[name=download]:checked')].map(el=>Number(el.value));if(!chosen.length){toast('Bitte mindestens einen Artikel auswählen.');break;}chosen.forEach(id=>articles.find(a=>a.id===id).offline=true);render();toast(`${chosen.length} Artikel offline · simuliert.`);break;}
    case 'remove-downloads':sheet('Offline-Dateien entfernen?','<p>Nur Downloads entfernen. Artikel und Merker bleiben erhalten.</p>'+action('remove-confirm','Offline-Dateien entfernen','btn wide'));break;
    case 'remove-confirm':articles.forEach(a=>a.offline=false);document.querySelector('#sheet').close();render();toast('Offline-Dateien im Entwurf entfernt.');break;
    case 'download-error':sheet('Ein Artikel konnte nicht geladen werden','<p>Die Quelle antwortet gerade nicht. Bereits gespeicherte Inhalte bleiben verfügbar.</p>'+action('retry-download','Erneut versuchen','btn wide'));break;
    case 'retry-download':document.querySelector('#sheet').close();toast('Erneuter Versuch simuliert. Download verfügbar.');break;
    case 'rule-preview':captureRule();if(!state.ruleTerm){toast('Bitte einen Begriff eingeben.');break;}sheet('Regelvorschau',`<p>${ruleMatches().length} passende Beiträge im Beispieldatensatz. Aktion: ${esc(state.ruleAction)}.</p>`+ruleMatches().map(articleCard).join(''));break;
    case 'rule-save':captureRule();if(!state.ruleTerm){toast('Bitte einen Begriff eingeben.');break;}state.rule=true;render();toast('Regel gespeichert. Automatik im Entwurf nur als Vorschau.');break;
    case 'rule-delete':state.rule=false;render();toast('Regel entfernt.');break;
    case 'hidden-items':sheet('Ausgeblendete Beiträge',state.rule&&state.ruleAction==='Ausblenden'&&ruleMatches().length?ruleMatches().map(articleCard).join(''):'<p>Die aktuelle Beispielregel blendet keine Beiträge aus.</p>');break;
    case 'clear-search':state.query='';render();document.querySelector('#search-query').focus();break;
    case 'run-search':state.query=value('search-query');state.searchFolder=value('search-folder');state.searchStatus=value('search-status');render();break;
    case 'save-view':state.query=value('search-query');state.searchFolder=value('search-folder');state.searchStatus=value('search-status');sheet('Suche als Ansicht speichern',field('Name','view-name',state.query||'Meine Ansicht')+action('view-save','Ansicht speichern','btn wide'));break;
    case 'view-save':if(!value('view-name').trim())return;state.savedViews.push({name:value('view-name').trim(),query:state.query,folder:state.searchFolder,status:state.searchStatus});navigate('rules');toast('Suchansicht gespeichert.');break;
    case 'view-open':{const v=state.savedViews[state.viewIndex];state.query=v.query;state.searchFolder=v.folder;state.searchStatus=v.status;navigate('search');break;}
    case 'view-rename':{const v=state.savedViews[state.viewIndex];v.name=value('view-edit').trim()||v.name;document.querySelector('#sheet').close();render();break;}
    case 'view-delete':state.savedViews.splice(state.viewIndex,1);document.querySelector('#sheet').close();render();break;
    case 'play':if(!state.queue.length){toast('Füge zuerst Artikel zur Warteschlange hinzu.');break;}state.playing=!state.playing;render();break;
    case 'next-audio':state.queue.shift();state.playing=false;render();break;
    case 'queue-up':{const i=state.queue.indexOf(id);if(i>0)[state.queue[i-1],state.queue[i]]=[state.queue[i],state.queue[i-1]];render();break;}
    case 'queue-remove':if(state.queue[0]===id)state.playing=false;state.queue=state.queue.filter(v=>v!==id);render();break;
    case 'queue-library':state.queue=articles.filter(a=>a.saved).map(a=>a.id);render();toast('Leseliste in Warteschlange übernommen.');break;
    case 'speed':button.textContent=button.textContent==='1×'?'1,25×':'1×';break;
    case 'voice-error':sheet('Keine passende Stimme','<p>In der App: eine Systemstimme installieren oder Sprache wechseln. Artikel bleibt normal lesbar.</p>');break;
    case 'settings-save':state.notices=value('notice-mode');state.interval=value('refresh-mode');state.noticeSources=value('notice-sources');state.digestTime=value('digest-time');state.quietHours=document.querySelector('#quiet-hours').checked;toast('Einstellungen für den Entwurf übernommen.');break;
    case 'notice-preview':sheet('So könnte ein Hinweis aussehen',panel('Candy · Deine Zusammenfassung','3 neue Beiträge · Android Journal und 2 weitere Quellen')+'<p>Bei gesperrtem Profil nur „Neue Beiträge verfügbar“.</p>');break;
    case 'permission-error':sheet('Benachrichtigungen nicht erlaubt','<p>Deine Auswahl bleibt gespeichert. Hinweise erscheinen erst, wenn Candy die Systemberechtigung erhält.</p>');break;
    case 'import-preview':toast('Beispiel geprüft: 2 neu, 1 vorhanden, 1 ungültig.');break;
    case 'import-confirm':state.importFolders=document.querySelector('#import-folders').checked;state.imported=true;render();toast('2 Beispielquellen importiert.');break;
    case 'export':sheet('OPML-Export','<p>Die App exportiert Abos und Ordner über den Dateidialog. Beispielinhalt:</p><pre style="white-space:pre-wrap;font-size:12px">Technik\n  Android Journal\n  Kotlin Notes\nPrivat\n  Open Web\n  Slow Sunday</pre><p>Im Entwurf wird keine Datei geschrieben.</p>');break;
    case 'reader-menu':sheet('Dein Lesemoment',action('reader-save',bookmarkIcon(a.saved)+(a.saved?'Gemerkt':'Für später merken'),'btn secondary wide bookmark-action')+row('↓','Offline speichern',a.offline?'Schon verfügbar':'Artikel auf dem Gerät behalten','reader-download')+row('▥','Bibliothek öffnen','Webseiten und Feed-Artikel gemeinsam','reader-library')+queueButton(a,true)+row('#','Tags','Artikel persönlich einordnen','tags')+row('→','Nächster ungelesener Beitrag','Im Reader weiterlesen','next-unread')+row('↗','Quelle öffnen','Reader schließen und Original ansehen','original')+(a.updated?row('↻','Änderungen ansehen','Vergleich mit gespeicherter Fassung','changes'):''));break;
    case 'reader-save':a.saved=!a.saved;button.innerHTML=bookmarkIcon(a.saved)+(a.saved?'Gemerkt':'Für später merken');break;
    case 'reader-download':a.offline=true;a.inLibrary=true;document.querySelector('#sheet').close();toast('Artikel offline gespeichert · simuliert.');break;
    case 'reader-library':if(frameRoute(routeHistory.at(-1))==='library'){closeSheet();goBack();}else navigate('library');break;
    case 'tags':sheet('Tags für diesen Artikel',field('Tags, durch Komma getrennt','article-tags',a.tags||'Lesenswert')+action('tags-save','Tags speichern','btn wide'));break;
    case 'tags-save':a.tags=value('article-tags');document.querySelector('#sheet').close();toast('Tags gespeichert: '+a.tags);break;
    case 'next-unread':{const next=feedArticles().find(a=>!a.read);if(next){state.article=next.id;next.read=true;navigate('reader');}else{document.querySelector('#sheet').close();toast('Alles gelesen.');}break;}
    case 'original':{const parent=routeHistory.pop();state.browserReturn=frameRoute(parent)==='browser'?null:parent||'library';state.browserArticle=state.article;navigate('browser',true);break;}
    case 'empty-demo':sheet('Deine Inbox ist bereit',empty('Welche Stimmen fehlen dir?','Abonniere eine Website oder importiere deine bisherigen Feeds.')+action('discover','Erste Quelle entdecken','btn wide'));break;
    case 'network-error':sheet('Feeds gerade nicht erreichbar','<p>Letzter erfolgreicher Abruf: heute, 08:10. Vorhandene Artikel bleiben lesbar.</p>'+action('retry-network','Erneut versuchen','btn wide'));break;
    case 'retry-network':document.querySelector('#sheet').close();toast('Demo-Verbindung wiederhergestellt.');break;
    case 'private-demo':sheet('Privater Browsermodus','<p>Keine Abos, Regeln, Lesestände oder Downloads werden dauerhaft gespeichert. Feed-Vorschau bleibt möglich.</p>'+action('discover','Vorschau ansehen','btn wide'));state.discoveryPrivate=true;break;
    case 'subscribed-feed':sheet('Field Notes',panel('Abonnement',esc(state.subscriptionFolder)+' · '+esc(state.subscriptionMode))+'<p>Die Quelle wurde in dieser Demo abonniert. Echte Beiträge werden nicht abgerufen.</p>');break;
    case 'imported-feed':sheet('Importierte Quelle','<p>Quelle im Demo-Profil ergänzt. Echte Beiträge werden im Entwurf nicht abgerufen.</p>');break;
    case 'future-details':sheet('Später verbinden',panel('Newsletter','Eigene Empfangsadresse oder Dienstanbindung. Eingang als Feed; Absender verwalten.')+panel('Podcasts','Audio-Abos, Downloads, Abspielposition und Wiedergabe im Hintergrund.')+panel('Synchronisierung','Abos, Ordner, Merker und Lesestände zwischen Geräten. Konflikte und Profilgrenzen ausdrücklich behandeln.')+'<p>Diese Erweiterungen sind noch keine aktiven Integrationen.</p>');break;
    default:if(act?.startsWith('feed-')){const feed=articles.find(a=>a.id===Number(act.slice(5)));state.editFeed=feed.id;const prefs=state.feedPreferences[feed.id]||{mode:'Reader-Volltext',folder:feed.topic,notice:false};sheet(feed.source,select('Standardansicht','feed-mode',['Reader-Volltext','Feed-Inhalt','Originalseite'],prefs.mode)+select('Ordner','feed-folder',folders(),prefs.folder)+check('Hinweise für diese Quelle','feed-notice',prefs.notice)+(feed.id===3?panel('Letzter Abruf fehlgeschlagen','Gespeicherte Beiträge bleiben lesbar. Nächster Versuch beim Aktualisieren.'):'')+'<p>Falls Volltext nicht verfügbar ist: Feed-Text zeigen, Originalseite anbieten.</p>'+action('feed-save','Übernehmen','btn wide'));}else if(act?.startsWith('view-')){state.viewIndex=Number(act.slice(5));const v=state.savedViews[state.viewIndex];sheet('Gespeicherte Ansicht',field('Name','view-edit',v.name)+action('view-open','Ansicht öffnen','btn wide')+action('view-rename','Umbenennen','text-btn wide')+action('view-delete','Ansicht löschen','text-btn wide'));}
  }
});
document.addEventListener('change',event=>{if(event.target.id==='dedup')state.dedup=event.target.checked;if(event.target.id==='wifi')state.wifi=event.target.checked;if(event.target.id==='budget')state.budget=event.target.value;});
document.addEventListener('input',event=>{if(event.target.id==='search-query')document.querySelector('[data-action=clear-search]').hidden=!event.target.value;});
document.addEventListener('submit',event=>event.preventDefault());
document.querySelector('.sheet-close').addEventListener('click',closeSheet);
document.querySelector('#sheet').addEventListener('close',()=>document.querySelector('.phone').classList.remove('menu-open'));
document.querySelector('#sheet').addEventListener('cancel',()=>{catalogPrototype.cancelPreview();document.querySelector('.phone').classList.remove('menu-open');});
document.querySelector('#theme').addEventListener('click',()=>{const dark=document.body.classList.toggle('dark');document.querySelector('#theme span').textContent=dark?'Hell ansehen':'Dunkel ansehen';});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
if(location.hash&&location.hash!=='#browser')routeHistory.push('browser');
navigate(location.hash.slice(1)||'browser',true);
